def count_beautiful_integers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_up_to(n):
        if n <= 0:
            return 0
        s = str(n)
        digits = [int(c) for c in s]
        length = len(digits)

        @lru_cache(None)
        def dp(pos, remainder, balance, tight, started):
            if pos == length:
                if started and balance == 0 and remainder == 0:
                    return 1
                return 0

            limit = digits[pos] if tight else 9
            total = 0

            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_started = started or (d != 0)

                if not new_started:
                    new_remainder = remainder
                    new_balance = balance
                else:
                    new_remainder = (remainder * 10 + d) % k
                    if d % 2 == 0:
                        new_balance = balance - 1
                    else:
                        new_balance = balance + 1

                total += dp(pos + 1, new_remainder, new_balance, new_tight, new_started)

            return total

        return dp(0, 0, 0, True, False)

    return count_up_to(high) - count_up_to(low - 1)
```

